def flush(self):
    self.file.flush()
    self.stdout.flush()

def close(self):
    if self.file:
        self.file.close()

def isatty(self):
    """返回False，表示这不是一个终端"""
    return False

def generic_aval(self, expr: ast.expr) -> Tuple[StoreAbles, AbstractValue]:
    """Called if no explicit visitor function exists for a node."""
    ret: ValueInfo = ValueInfo.get_any()
    all_store_ables: List[StoreAble] = []
    use_avaler = ExprAnalyzer(self.manager, self._package_db, self._current_db, self._typing_entities, UseContext(),
                              self._builder, self._env)
    for field, value in ast.iter_fields(expr):
        if isinstance(value, list):
            for item in value:
                if isinstance(item, ast.expr):

                    store_ables, avalue = use_avaler.aval(item)
                    all_store_ables.extend(store_ables)
                    for _, ent_type in avalue:
                        ret = ret.join(ent_type)
        elif isinstance(value, ast.expr):
            store_ables, avalue = use_avaler.aval(value)
            all_store_ables.extend(store_ables)
            for _, ent_type in avalue:
                ret = ret.join(ent_type)

    return all_store_ables, [(get_anonymous_ent(), ret)]

def aval_Constant(self, constant: ast.Constant) -> Tuple[StoreAbles, AbstractValue]:
    constant_cls: Optional[Class] = None
    if isinstance(constant.value, str):
        constant_cls = self.get_class_from_builtins(ConstantKind.string.value)
    s = self._builder.add_move_temp(Constant(constant, constant_cls), constant)
    return [s], []

def build_move_by_context(self, stores: StoreAbles) -> None:
    match self._exp_ctx:
        case SetContext() as ctx:
            for lhs, rhs in itertools.product(stores, ctx.rhs_store_ables):
                self._builder.add_move(lhs, rhs)

def aval_Subscript(self, subscript: ast.Subscript) -> Tuple[StoreAbles, AbstractValue]:
    _, _ = self.aval(subscript.slice)
    base_stores, abstract_value = self.aval(subscript.value)
    if isinstance(subscript.slice, ast.Slice):
        index_accesses = base_stores
    else:
        index_accesses = self._builder.load_index(base_stores, self._exp_ctx, subscript)
    return index_accesses, abstract_value

def get_use_avaler(self) -> "ExprAnalyzer":
    return ExprAnalyzer(self.manager, self._package_db, self._current_db, None,
                        UseContext(), self._builder, self._env)

def get_class_from_builtins(self, name: str) -> "Optional[Class]":
    if entities := self.get_from_builtins(name):
        first_result = entities[0][0]
        if isinstance(first_result, Class):
            return first_result
    return None

def extend_known_possible_attribute(manager: AnalyzeManager,
                                    attribute: str,
                                    possible_ents: AbstractValue,
                                    ret: AbstractValue,
                                    package_db: RootDB,
                                    current_db: ModuleDB) -> None:
    for ent, ent_type in possible_ents:
        if isinstance(ent_type, InstanceType):
            class_attrs = ent_type.lookup_attr(attribute)
            process_known_attr(class_attrs, attribute, ret, current_db, ent_type.class_ent, ent_type)
        elif isinstance(ent_type, ConstructorType):
            class_attrs = ent_type.lookup_attr(attribute)
            process_known_attr(class_attrs, attribute, ret, current_db, ent_type.class_ent, ent_type)
        elif isinstance(ent_type, ModuleType):
            if isinstance(ent, Module):
                manager.strict_analyze_module(ent)
            module_level_ents = ent_type.namespace[attribute]
            process_known_attr(module_level_ents, attribute, ret, current_db, ent, ent_type)
        elif isinstance(ent_type, PackageType):
            package_level_ents = ent_type.namespace[attribute]
            process_known_attr(package_level_ents, attribute, ret, current_db, ent, ent_type)
        elif isinstance(ent_type, AnyType):
            location = Location.global_name(attribute)
            referenced_attr = ReferencedAttribute(location.to_longname(), location)
            current_db.add_ent(referenced_attr)
            ret.append((referenced_attr, ValueInfo.get_any()))
        else:
            raise NotImplementedError("attribute receiver entity matching not implemented")

def extend_known_or_new_possible_attribute(manager: AnalyzeManager,
                                           attribute: str,
                                           possible_ents: AbstractValue,
                                           ret: SetContextValue,
                                           package_db: RootDB,
                                           current_db: ModuleDB) -> None:
    for ent, ent_type in possible_ents:
        if isinstance(ent_type, InstanceType):
            class_attrs = ent_type.lookup_attr(attribute)
            process_known_or_newly_created_attr(class_attrs, attribute, ret, current_db, ent_type.class_ent, ent_type)
        elif isinstance(ent_type, ConstructorType):
            class_attrs = ent_type.lookup_attr(attribute)
            process_known_or_newly_created_attr(class_attrs, attribute, ret, current_db, ent_type.class_ent, ent_type)
        elif isinstance(ent_type, ModuleType):
            if isinstance(ent, Module):
                manager.strict_analyze_module(ent)
            module_level_ents = ent_type.namespace[attribute]
            process_known_or_newly_created_attr(module_level_ents, attribute, ret, current_db, ent, ent_type)
        elif isinstance(ent_type, PackageType):
            package_level_ents = ent_type.namespace[attribute]
            process_known_or_newly_created_attr(package_level_ents, attribute, ret, current_db, ent, ent_type)
        elif isinstance(ent_type, AnyType):
            location = Location.global_name(attribute)
            referenced_attr = ReferencedAttribute(location.to_longname(), location)
            current_db.add_ent(referenced_attr)
            ret.append((referenced_attr, ValueInfo.get_any()))
        else:
            raise NotImplementedError("attribute receiver entity matching not implemented")

def filter_not_setable_entities(ent_objs: AbstractValue) -> AbstractValue:
    ret = []
    for e, v in ent_objs:
        if not isinstance(e, (Class, Function, Module, ModuleAlias)):
            ret.append((e, v))
    return ret

def __init__(self) -> None:
    self.finished_module_set: ty.Set[Path] = set()
    self.checking_stack: ty.List[Path] = []

def add_ent(self, ent: "Entity") -> None:
    if ent.id not in self.ent_id_set:
        self.ent_id_set.add(ent.id)
        self.dep_db.add_ent(ent)

def parse_a_module(self, module_path: Path) -> ast.Module:
    absolute_path = self.project_root.parent.joinpath(module_path)
    try:
        return ast.parse(absolute_path.read_text(encoding="utf-8"), module_path.name)
    except (SyntaxError, UnicodeDecodeError):
        return ast.Module([])

def get_module_level_bindings(self) -> "Bindings":
    bindings: Bindings = []
    for name, ents in self.module_ent.names.items():
        bound_ents = [(ent, ent.direct_type()) for ent in ents]
        bindings.append((name, bound_ents))
    return bindings

def initialize_tree(self, path: Path) -> ty.List[Path]:
    py_files: ty.List[Path] = []
    rel_path = path.relative_to(self.root_dir.parent)
    if path.is_file() and path.name.endswith(".py"):
        py_files.append(rel_path)
        from enre.dep.DepDB import DepDB
        module_ent = Module(rel_path)
        self.tree[rel_path] = ModuleDB(self.root_dir, module_ent)
    elif path.is_dir():
        sub_py_files = []
        for file in path.iterdir():
            sub_py_files.extend(self.initialize_tree(file))
        py_files.extend(sub_py_files)
        if sub_py_files:
            package_ent = Package(rel_path)
            self.global_db.add_ent(package_ent)
            self.package_tree[rel_path] = package_ent
            for file in path.iterdir():
                sub_path = file.relative_to(self.root_dir.parent)
                if sub_path in self.package_tree:
                    sub_package_ent = self.package_tree[sub_path]
                    package_ent.add_ref(Ref(RefKind.ContainKind, sub_package_ent, 0, 0, False, None))
                elif sub_path in self.tree:
                    module_ent = self.tree[sub_path].module_ent
                    package_ent.add_ref(Ref(RefKind.ContainKind, module_ent, 0, 0, False, None))

    return py_files

def get_path_ent(self, path: Path) -> ty.Union["Package", "Module"]:
    if path in self.tree:
        return self.tree[path].module_ent
    else:
        return self.package_tree[path]

def dir_structure_init(self, file_path: ty.Optional[Path] = None) -> bool:
    in_package = False
    if file_path is None:
        file_path = self.project_root

    if file_path.is_dir():

        for sub_file_path in file_path.iterdir():
            if self.dir_structure_init(sub_file_path):
                in_package = True
        if in_package:
            package_ent = Package(file_path.relative_to(self.project_root.parent))
            # todo: create dependency tree per file
            self.root_db.add_ent_global(package_ent)

    elif file_path.name.endswith(".py"):
        in_package = True

    return in_package

def iter_dir(self, path: Path) -> None:
    from enre.analysis.analyze_stmt import Analyzer

    if path.is_dir():
        for sub_file in path.iterdir():
            self.iter_dir(sub_file)
    elif path.name.endswith(".py"):
        rel_path = path.relative_to(self.project_root.parent)
        print(rel_path)
        if self.module_stack.finished_module(rel_path):
            print(f"the module {rel_path} already imported by some analyzed module")
            return
        else:
            self.module_stack.push(rel_path)
            self.analyze_module_top_stmts(rel_path)
            self.module_stack.pop()

def import_module(self, from_module_ent: Module, module_identifier: str,
                  lineno: int, col_offset: int, strict: bool) -> ty.Tuple[
    ty.Union[Module, Package], ty.Union[Module, Package]]:
    rel_path, head_module_path = self.alias2path(from_module_ent.module_path, module_identifier)
    if self.need_analyze(rel_path):
        return self.root_db.get_module_db_of_path(rel_path).module_ent, self.root_db.get_path_ent(head_module_path)
    elif (p := self.resolve_import(from_module_ent, rel_path)) is not None:
        if p.is_file():
            module_ent = self.root_db.get_module_db_of_path(rel_path).module_ent
            if strict:
                self.strict_analyze_module(module_ent)
            return module_ent, self.root_db.get_path_ent(head_module_path)
        elif rel_path in self.root_db.package_tree:
            package_ent = self.root_db.package_tree[rel_path]
            if p.joinpath("__init__.py").exists():
                return self.import_module(from_module_ent, f"{module_identifier}.__init__", lineno, col_offset,
                                          strict)
            return package_ent, self.root_db.get_path_ent(rel_path)
        else:
            package_ent = Package(rel_path)
            self.root_db.package_tree[rel_path] = package_ent
            return package_ent, self.root_db.get_path_ent(rel_path)
    else:
        unknown_module_name = module_identifier.split(".")[-1]
        unknown_module_ent = UnknownModule(unknown_module_name)
        module_db = self.root_db.get_module_db_of_path(from_module_ent.module_path)
        module_db.add_ent(unknown_module_ent)
        from_module_ent.add_ref(Ref(RefKind.ImportKind, unknown_module_ent, lineno, col_offset, False, None))
        return unknown_module_ent, unknown_module_ent
        # raise NotImplementedError("unknown module not implemented yet")

def alias2path(self, from_path: Path, alias: str) -> ty.Tuple[Path, Path]:
    def resolve_head_path(imported_path: Path, head_path: Path) -> ty.Tuple[Path, Path]:
        if str(imported_path) == str(head_path) + ".py":
            return imported_path, imported_path
        else:
            return imported_path, head_path

    path_elems = alias.split(".")
    head_module_name = path_elems[0]
    rel_path = Path("/".join(path_elems) + ".py")
    dir_rel_path = Path("/".join(path_elems))
    from_path = from_path.parent
    while True:
        if from_path == Path():
            break
        if self.project_root.parent.joinpath(from_path).joinpath(rel_path).exists():
            return resolve_head_path(from_path.joinpath(rel_path), from_path.joinpath(head_module_name))
        elif self.project_root.parent.joinpath(from_path).joinpath(dir_rel_path).exists():
            return resolve_head_path(from_path.joinpath(dir_rel_path), from_path.joinpath(head_module_name))
        from_path = from_path.parent
    return rel_path, from_path.joinpath(head_module_name)

def get_from_builtins(self, name: str) -> "ty.Optional[AbstractValue]":
    if self.builtins_bindings:
        return get_from_bindings(name, self.builtins_bindings)
    else:
        return None

def resolve_import(self, from_module: Module, rel_path: Path) -> ty.Optional[Path]:
    project_root = self.project_root
    parent_dir = project_root.parent.joinpath(from_module.module_path.parent)
    while True:
        target_module_path = parent_dir.joinpath(rel_path)
        if target_module_path.exists() and target_module_path.relative_to(project_root.parent) in self.root_db.tree:
            return target_module_path
        if parent_dir.samefile(project_root.parent):
            break
        parent_dir = parent_dir.parent

    return None

def in_root_db(self, path: Path) -> bool:
    project_root = self.project_root
    return path.exists() and path.relative_to(project_root.parent) in self.root_db.tree

def resolve_head_path(imported_path: Path, head_path: Path) -> ty.Tuple[Path, Path]:
    if str(imported_path) == str(head_path) + ".py":
        return imported_path, imported_path
    else:
        return imported_path, head_path

def __init__(self) -> None:
    self.abstract_methods: List[Function] = []
    self.inherit: Optional[str] = None

def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
    self.current_func_name = node.name
    for decorator in node.decorator_list:
        if type(decorator) == ast.Name:
            if decorator.id == 'abstractmethod':
                if node.name.startswith("__") and node.name.endswith("__"):
                    self.abstract_kind = FunctionKind.Constructor
                else:
                    self.abstract_kind = FunctionKind.AbstractMethod
            elif decorator.id == 'staticmethod':
                self.static_kind = FunctionKind.StaticMethod
            elif decorator.id == 'property':
                self.readonly_property_name = node.name
    # 如果普通函数的函数体中只有raise NotImplementError的话也算是抽象函数
    if len(node.body) == 1 and type(node.body[0]) == ast.Raise:
        self.visit_Raise(node.body[0])
        if self.have_raise_NotImplementedError:
            self.abstract_kind = FunctionKind.AbstractMethod

    # 这里是根据return返回属性判断的，判断逻辑不全，已舍弃
    # if self.have_property_decorator and len(node.body) == 1:
    #     if type(node.body[0]) == ast.Return and type(node.body[0].value) == ast.Attribute:
    #         self.readonly_property_name = node.body[0].value.attr

def visit_Raise(self, node: ast.Raise) -> None:
    if type(node.exc) == ast.Call:
        if type(node.exc.func) == ast.Name and node.exc.func.id == 'NotImplementedError':
            if self.current_func_name.startswith("__") and self.current_func_name.endswith("__"):
                self.abstract_kind = FunctionKind.Constructor
            else:
                self.have_raise_NotImplementedError = True
    self.generic_visit(node)

def generic_analyze(self, stmt: ast.AST, env: EntEnv) -> None:
    """Called if no explicit visitor function exists for a node."""
    default_avaler = self.get_default_avaler(env)
    for field, value in ast.iter_fields(stmt):
        if isinstance(value, list):
            for item in value:
                if isinstance(item, ast.expr):
                    default_avaler.aval(item)
                elif isinstance(item, ast.AST):
                    self.analyze(item, env)
        elif isinstance(value, ast.AST):
            self.analyze(value, env)

def analyze_AugAssign(self, aug_stmt: ast.AugAssign, env: EntEnv) -> None:
    target_expr = aug_stmt.target
    rvalue_expr = aug_stmt.value
    if rvalue_expr is not None:
        self.process_assign_helper(rvalue_expr, [target_expr], env, None)
    else:
        self.declare_semantic(target_expr, env)

def analyze_Expr(self, expr_stmt: ast.Expr, env: EntEnv) -> None:
    avaler = self.get_default_avaler(env)
    avaler.aval(expr_stmt.value)

def analyze_Import(self, import_stmt: ast.Import, env: EntEnv) -> None:
    def create_proper_alias(file_ent: ty.Union[Module, Package], location: Location) -> Entity:
        if isinstance(file_ent, Module):
            return ModuleAlias(file_ent, location)
        else:
            return PackageAlias(file_ent, location)

    for module_alias in import_stmt.names:
        path_ent, bound_ent = self.manager.import_module(self.module, module_alias.name, import_stmt.lineno,
                                                         import_stmt.col_offset, False)
        bound_name = bound_ent.longname.name
        if module_alias.asname is None:
            module_binding: Bindings = [(bound_name, [(bound_ent, PackageType(bound_ent.names))])]
            env.get_scope().add_continuous(module_binding)
        else:
            alias_location = env.get_ctx().location.append(module_alias.asname, Span.get_nil(), None)
            alias_ent = create_proper_alias(path_ent, alias_location)
            self.current_db.add_ent(alias_ent)
            alias_binding: Bindings = [(module_alias.asname, [(alias_ent, ModuleType(path_ent.names))])]
            env.get_scope().add_continuous(alias_binding)
        env.get_ctx().add_ref(Ref(RefKind.ImportKind, path_ent, import_stmt.lineno,
                                  import_stmt.col_offset, False, None))

def analyze_stmts(self, stmts: ty.List[ast.stmt], env: EntEnv) -> None:
    for stmt in stmts:
        self.analyze(stmt, env)

def get_default_avaler(self, env: EntEnv) -> ExprAnalyzer:
    return ExprAnalyzer(self.manager, self.package_db, self.current_db, None, UseContext(),
                        env.get_scope().get_builder(), env)

def process_annotation(typing_ent: Entity, manager: AnalyzeManager, package_db: RootDB, current_db: ModuleDB,
                       annotation: ty.Optional[ast.expr], env: EntEnv) -> None:
    if annotation is not None:
        avaler = ExprAnalyzer(manager, package_db, current_db, [typing_ent],
                              UseContext(), env.get_scope().get_builder(), env)
        avaler.aval(annotation)

def process_parameters(args: ast.arguments, scope: ScopeEnv, env: EntEnv, manager: AnalyzeManager, package_db: RootDB,
                       current_db: ModuleDB, func_ent: Entity, summary: FunctionSummary,
                       class_ctx: ty.Optional[Class] = None) -> None:
    location_base = scope.get_location()
    ctx_fun = scope.get_ctx()
    para_constructor = LambdaParameter if isinstance(scope.get_ctx(), LambdaFunction) else Parameter

    def process_helper(a: ast.arg, ent_type: ValueInfo, bindings: "Bindings", arg_kind: ArgKind) -> None:
        para_code_span = get_syntactic_span(a)
        parameter_loc = location_base.append(a.arg, para_code_span, current_db.module_path)
        parameter_ent = para_constructor(func_ent, parameter_loc.to_longname(), parameter_loc)
        current_db.add_ent(parameter_ent)
        new_coming_ent: Entity = parameter_ent
        bindings.append((a.arg, [(new_coming_ent, ent_type)]))
        if arg_kind == PArg:
            summary.positional_para_list.append(a.arg)
        elif arg_kind == VarArg:
            summary.var_para = a.arg
        elif arg_kind == KWArg:
            summary.kwarg = a.arg
        else:
            assert False, "never reach"
        ctx_fun.add_ref(
            Ref(RefKind.DefineKind, parameter_ent, a.lineno, a.col_offset, a.annotation is not None, None))
        process_annotation(parameter_ent, manager, package_db, current_db, a.annotation, env)

    args_binding: "Bindings" = []

    for arg in args.posonlyargs:
        process_helper(arg, ValueInfo.get_any(), args_binding, PArg)

    if len(args.args) >= 1:
        first_arg = args.args[0].arg
        if first_arg == "self":
            if class_ctx is not None:
                class_type: ValueInfo = InstanceType(class_ctx)
            else:
                class_type = ValueInfo.get_any()
            process_helper(args.args[0], class_type, args_binding, PArg)
        elif first_arg == "cls":
            if class_ctx is not None:
                constructor_type: ValueInfo = ConstructorType(class_ctx)
            else:
                constructor_type = ValueInfo.get_any()
            process_helper(args.args[0], constructor_type, args_binding, PArg)
        else:
            process_helper(args.args[0], ValueInfo.get_any(), args_binding, PArg)

    for arg in args.args[1:]:
        process_helper(arg, ValueInfo.get_any(), args_binding, PArg)
    if args.vararg is not None:
        process_helper(args.vararg, ValueInfo.get_any(), args_binding, VarArg)
    for arg in args.kwonlyargs:
        process_helper(arg, ValueInfo.get_any(), args_binding, KWArg)
    if args.kwarg is not None:
        process_helper(args.kwarg, ValueInfo.get_any(), args_binding, KWArg)

    scope.add_continuous(args_binding)

def create_proper_alias(file_ent: ty.Union[Module, Package], location: Location) -> Entity:
    if isinstance(file_ent, Module):
        return ModuleAlias(file_ent, location)
    else:
        return PackageAlias(file_ent, location)

def visit(self, node: ast.expr) -> "Target":
    method = 'visit_' + node.__class__.__name__
    visitor: Callable[[ast.expr], "Target"] = getattr(self, method, self.visit_Lvalue)
    return visitor(node)

def visit_List(self, node: ast.List) -> "ListTar":
    tar_list: List[Target] = []
    for e in node.elts:
        tar_list.append(self.visit(e))
    return ListTar(tar_list)

def visit_Tuple(self, node: ast.Tuple) -> "TupleTar":
    tar_list: List[Target] = []
    for e in node.elts:
        tar_list.append(self.visit(e))
    return TupleTar(tar_list)

def dummy_unpack(_: AbstractValue) -> MemberDistiller:
    def wrapper(_: int) -> AbstractValue:
        return [(get_anonymous_ent(), ValueInfo.get_any())]

    return wrapper

def compress_abstract_value(entities: AbstractValue) -> AbstractValue:
    new_entities_dict: Dict[Entity, Set[ValueInfo]] = defaultdict(set)
    for ent, ent_type in entities:
        new_entities_dict[ent].add(ent_type)
    new_entities: AbstractValue = []
    for ent, ent_types in new_entities_dict.items():
        for ent_type in ent_types:
            new_entities.append((ent, ent_type))
    return new_entities

def flatten_bindings(bindings: "Bindings") -> "Bindings":
    binding_dict: Dict[str, AbstractValue] = defaultdict(list)
    for name, abstract_val in bindings:
        binding_dict[name].extend(abstract_val)
    new_bindings: "Bindings" = list(binding_dict.items())
    for i in range(0, len(new_bindings)):
        new_bindings[i] = new_bindings[i][0], compress_abstract_value(new_bindings[i][1])
    return new_bindings

def abstract_assign(lvalue: SetContextValue, rvalue: AbstractValue, assigned_expr: ast.expr,
                    r_store_ables: StoreAbles,
                    builder: SummaryBuilder,
                    ctx: "AnalyzeContext") -> StoreAbles:
    new_bindings: "Bindings" = []
    for _, value_type in rvalue:
        for target in lvalue:
            assign_semantic(target, value_type, new_bindings, ctx)
    new_bindings = flatten_bindings(new_bindings)
    ctx.env.get_scope().add_continuous(new_bindings)

    lhs_store_ables = []
    for n, target_ents in new_bindings:
        for tar, _ in target_ents:
            lhs_store_able = get_named_store_able(ctx.env.get_ctx(), tar, assigned_expr)
            if lhs_store_able:
                lhs_store_ables.append(lhs_store_able)
    return lhs_store_ables

def assign2target(target: ast.expr, rvalue_expr: Optional[ast.expr], builder: SummaryBuilder,
                  ctx: "AnalyzeContext") -> Iterable[Entity]:
    from enre.analysis.analyze_expr import ExprAnalyzer, UseContext
    rvalue: AbstractValue
    r_store_ables: StoreAbles
    if rvalue_expr is None:
        rvalue = [(get_anonymous_ent(), ValueInfo.get_any())]
        r_store_ables = []
    else:
        avaler = ExprAnalyzer(ctx.manager, ctx.package_db, ctx.current_db, None, UseContext(), builder, ctx.env)
        r_store_ables, rvalue = avaler.aval(rvalue_expr)
    return unpack_semantic(target, rvalue, r_store_ables, builder, ctx)

def __init__(self, found_entities: "AbstractValue", must_found: bool) -> None:
    self._found_entities: AbstractValue = found_entities
    self._must_found = must_found

def get_from_bindings(name: str, bindings: "Bindings") -> "AbstractValue":
    ret = []
    for n, binds in bindings:
        if n == name:
            ret.extend(binds)
    return ret

def __init__(self, pairs: "Optional[Bindings]" = None):
    super().__init__(1)
    if pairs is None:
        pairs = []
    self._bindings_list = [pairs]

def get(self, name: str) -> SubEnvLookupResult:
    for bindings in reversed(self._bindings_list):
        ret = get_from_bindings(name, bindings)
        if ret:
            return SubEnvLookupResult(ret, True)
    return SubEnvLookupResult([], False)

def create_continuous_bindings(self, pairs: "Bindings") -> "SubEnv":
    self._bindings_list.append(pairs)
    return self

def get(self, name: str) -> SubEnvLookupResult:
    look_up_res1 = self._branch1_sub_env.get(name)
    look_up_res2 = self._branch2_sub_env.get(name)
    is_must_found = look_up_res1.must_found and look_up_res2.must_found
    found_entities = look_up_res1.found_entities + look_up_res2.found_entities
    return SubEnvLookupResult(found_entities, is_must_found)

def create_continuous_bindings(self, pairs: "Bindings") -> "SubEnv":
    new_sub_env = BasicSubEnv(pairs)
    return ContinuousSubEnv(self, new_sub_env)

def get(self, name: str) -> SubEnvLookupResult:
    backward_lookup_res = self._backward.get(name)
    # print(f"finding name {name} in env {self}")
    if backward_lookup_res.must_found:
        return backward_lookup_res
    else:
        # print(f"name {name} not found continue find at {self._forward}")
        forward_lookup_res = self._forward.get(name)
        found_entities = backward_lookup_res.found_entities + forward_lookup_res.found_entities
        return SubEnvLookupResult(found_entities, forward_lookup_res.must_found)

def create_continuous_bindings(self, pairs: "Bindings") -> "SubEnv":
    self._backward = self._backward.create_continuous_bindings(pairs)
    return self

def __init__(self, sub_env: SubEnv) -> None:
    super().__init__(sub_env.depth + 1)
    self._optional = sub_env

def get(self, name: str) -> SubEnvLookupResult:
    optional_lookup_res = self._optional.get(name)
    return SubEnvLookupResult(optional_lookup_res.found_entities, False)

def create_continuous_bindings(self, pairs: "Bindings") -> "SubEnv":
    new_sub_env = BasicSubEnv(pairs)
    return ContinuousSubEnv(self, new_sub_env)

def __init__(self, stmts: List[ast.stmt], scope_env: "ScopeEnv"):
    self.stmts: List[ast.stmt] = stmts
    self.scope_env: "ScopeEnv" = scope_env

def get(self, name: str) -> SubEnvLookupResult:
    ret = []
    for sub_env in reversed(self._sub_envs):
        lookup_res = sub_env.get(name)
        sub_ents = lookup_res.found_entities
        ret.extend(sub_ents)
        if lookup_res.must_found:
            return SubEnvLookupResult(ret, True)

    return SubEnvLookupResult(ret, False)

def get_class_ctx(self) -> "Optional[Class]":
    for scope_env in reversed(self.scope_envs):
        if scope_env.get_class_ctx() is not None:
            return scope_env.get_class_ctx()
    return None

def get(self, name: str) -> SubEnvLookupResult:
    possible_ents: AbstractValue = []
    for scope_env in reversed(self.scope_envs):
        lookup_res = scope_env.get(name)
        ents_in_scope = lookup_res.found_entities
        possible_ents.extend(ents_in_scope)
        if lookup_res.must_found:
            return SubEnvLookupResult(possible_ents, True)
    return SubEnvLookupResult(possible_ents, False)

def abstract_capture(name: str, err_constructor: AbstractValue, ctx: "AnalyzeContext") -> None:
    frame_entities: AbstractValue = []
    new_bindings: "Bindings" = []
    new_var_ent = UnknownVar(name)
    newly_create = NewlyCreated(Span.get_nil(), new_var_ent)
    for ent, ent_type in err_constructor:
        if isinstance(ent_type, ConstructorType):
            assign_semantic(newly_create, ent_type.to_class_type(), new_bindings, ctx)
        else:
            assign_semantic(newly_create, ValueInfo.get_any(), new_bindings, ctx)
    new_bindings = flatten_bindings(new_bindings)
    ctx.env.get_scope().add_continuous(new_bindings)

def handler_semantic(name: Optional[str], error_expr: ast.Expr, ctx: "AnalyzeContext") -> None:
    return
    use_avaler = ExprAnalyzer(ctx.manager, ctx.package_db, ctx.current_db)
    err_constructor = use_avaler.aval(error_expr.value, ctx.env)
    if name is not None:
        abstract_capture(name, err_constructor, ctx)

def join(self, rhs: "ValueInfo") -> "ValueInfo":
    if isinstance(rhs, ConstructorType) and rhs.class_ent == self.class_ent:
        return self
    else:
        return ValueInfo.get_any()

def __init__(self) -> None:
    self.sources = set()
    self.graph: Dict[Entity, Set[Entity]] = defaultdict(set)

def add_call(self, source: Optional[Entity], target: Entity) -> None:
    if not source:
        return
    self.sources.add(source)
    self.graph[source].add(target)

def update_if_not_contain_all(lhs: Set["HeapObject"], rhs: typing.Iterable["HeapObject"]) -> bool:
    # return True if all rhs objects have been already contained
    if lhs.issuperset(rhs):
        return True
    else:
        lhs.update(rhs)
        return False

def get_member(self, name: str, obj_slot: "ObjectSlot") -> None:
    this_class_member = self.namespace[name]
    obj_slot.update(this_class_member)
    if this_class_member:
        # if name already contained by class object, stop further lookup
        return
    else:
        for base in self.inherits:
            temp: "ObjectSlot" = set()
            base.get_member(name, temp)
            obj_slot.update(temp)
        return

def add_base(self, obj: "ClassObject") -> bool:
    if obj in self.inherits:
        return True
    else:
        self.inherits.add(obj)
        return False

def get_member(self, name: str, obj_slot: "ObjectSlot") -> None:
    # We can't get member of function yet
    return

def write_field(self, name: str, objs: "ReadOnlyObjectSlot") -> bool:
    # We can't write member of function yet
    return True

def __eq__(self, other: object) -> bool:
    return isinstance(other,
                      InstanceMethodReference) and self.func_obj == other.func_obj and self.from_obj == other.from_obj

def get_attribute_from_class_instance(instance: InstanceObject | IndexableObject | ConstantInstance, attr: str,
                                      obj_slot: "ObjectSlot") -> None:
    def extend_method_ref_is_not_exist(obj: "HeapObject", slot: "ObjectSlot") -> None:
        if isinstance(obj, FunctionObject):
            if not contain_same_ref(obj, instance, slot):
                slot.add(InstanceMethodReference(obj, instance))
                # todo: create instance method only when it's not exist already
        else:
            slot.add(obj)

    if attr in instance.namespace:
        obj_slot.update(instance.namespace[attr])
    else:
        cls_member: ObjectSlot = set()
        class_object: typing.Optional[ClassObject]
        if isinstance(instance, InstanceObject):
            class_object = instance.class_obj
        elif isinstance(instance, IndexableObject):
            class_object = instance.info
        elif isinstance(instance, ConstantInstance):
            class_object = instance.info
        else:
            assert False
        if class_object is not None:
            class_object.get_member(attr, cls_member)
            for obj in cls_member:
                extend_method_ref_is_not_exist(obj, obj_slot)

def contain_same_ref(obj1: FunctionObject, obj2: InstanceObject | IndexableObject | ConstantInstance,
                     slot: ObjectSlot) -> bool:
    for obj in slot:
        if isinstance(obj, InstanceMethodReference):
            if obj.func_obj == obj1 and obj.from_obj == obj2:
                return True
    return False

def extend_method_ref_is_not_exist(obj: "HeapObject", slot: "ObjectSlot") -> None:
    if isinstance(obj, FunctionObject):
        if not contain_same_ref(obj, instance, slot):
            slot.add(InstanceMethodReference(obj, instance))
            # todo: create instance method only when it's not exist already
    else:
        slot.add(obj)

def __str__(self) -> str:
    ret = "{}\n".format(self.module_head)
    for rule in self.rules:
        ret += "\t{}\n".format(str(rule))
    return ret

def get_invokes(self) -> "Iterable[Invoke]":
    rules = self.rules
    invokes = set()
    for r in rules:
        if isinstance(r, ValueFlow) and isinstance(r.rhs, Invoke):
            invokes.add(r.rhs)
        elif isinstance(r, Return) and isinstance(r.ret_value, Invoke):
            invokes.add(r.ret_value)
        elif isinstance(r, AddBase):
            for base in r.bases:
                if isinstance(base, Invoke):
                    invokes.add(base)
    return invokes

def get_object(self) -> ModuleObject:
    if self._correspond_obj:
        return self._correspond_obj
    else:
        namespace = defaultdict(set)
        for child in self._children:
            namespace[child.name()].add(child.get_object())
        new_obj = ModuleObject(self.module, self, namespace)
        self._correspond_obj = new_obj
        return new_obj

def get_object(self) -> ClassObject:
    if self._correspond_obj:
        return self._correspond_obj
    else:
        namespace = defaultdict(set)
        for child in self._children:
            namespace[child.name()].add(child.get_object())
        new_obj = ClassObject(self.cls, self, namespace)
        self._correspond_obj = new_obj
        return new_obj

def get_object(self) -> FunctionObject:
    if self._correspond_obj:
        return self._correspond_obj
    else:
        from enre.cfg.HeapObject import IndexableObject
        new_obj = FunctionObject(self.func, self)
        self._correspond_obj = new_obj
        if self.var_para:
            new_obj.namespace[self.var_para].add(IndexableObject(None, None))
        if self.kwarg:
            new_obj.namespace[self.kwarg].add(IndexableObject(None, None))
        return new_obj

def add_child(self, child: "ModuleSummary") -> None:
    return
    # todo: remove this method in the future

def __init__(self) -> None:
    self.summaries: List[ModuleSummary] = []
    self.summary_map: Dict[Entity, ModuleSummary] = dict()

def __init__(self, name: str, expr: ast.expr) -> None:
    self._name: str = name
    self._expr: ast.expr = expr

def __init__(self, parameter: Parameter, expr: ast.expr) -> None:
    self._parameter = parameter
    self._expr = expr

def __init__(self, variable: Variable, scope: Entity) -> None:
    self._varialbe = variable
    self.scope = scope

def add_inherit(self, cls: Class, args: List[StoreAbles]) -> None:
    cls_store = ClassConst(cls)
    for args_stores in list(itertools.product(*(args))):
        add_base = AddBase(cls_store, args_stores)
        self._rules.append(add_base)

def load_field(self, field_accesses: StoreAbles, field: str, context: "ExpressionContext",
               expr: ast.expr) -> StoreAbles:
    from enre.analysis.analyze_expr import SetContext
    ret: List[StoreAble] = []
    for fa in field_accesses:
        field_access = FieldAccess(fa, field, expr)
        if isinstance(context, SetContext):
            self.add_move_temp(field_access, expr)
            ret.append(field_access)
        else:
            ret.append(self.add_move_temp(field_access, expr))
        # we have to return a field access here, because only this can resolve set behavior correctly
    return ret

def load_index(self, bases: StoreAbles, context: "ExpressionContext", expr: ast.expr) -> StoreAbles:
    from enre.analysis.analyze_expr import SetContext
    ret: List[StoreAble] = []
    for base in bases:
        index_access = IndexAccess(base, expr)
        if isinstance(context, SetContext):
            self.add_move_temp(index_access, expr)
            ret.append(index_access)
        else:
            ret.append(self.add_move_temp(index_access, expr))
    return ret

def load_index_rvalues(self, bases: StoreAbles, expr: ast.expr) -> StoreAbles:
    ret: List[StoreAble] = []
    for base in bases:
        index_access = IndexAccess(base, expr)
        ret.append(self.add_move_temp(index_access, expr))
    return ret

def add_return(self, return_stores: StoreAbles, expr: ast.expr) -> None:
    assert isinstance(self.mod, FunctionSummary)
    for return_store in return_stores:
        self.add_store_able(return_store)
        self._rules.append(Return(return_store, expr))

def add_list(self, info: IndexableInfo, lst_stores: StoreAbles, expr: ast.expr) -> None:
    for lst_store in lst_stores:
        self.add_store_able(lst_store)
        self._rules.append(AddList(info, lst_store, expr))

def is_object_of_type(cls: Class, lhs: HeapObject) -> bool:
    if isinstance(lhs, InstanceObject) and lhs.class_obj.class_ent == cls:
        return True
    elif isinstance(lhs, IndexableObject) and lhs.info and lhs.info.class_ent == cls:
        return True
    elif isinstance(lhs, ConstantInstance) and lhs.info and lhs.info.class_ent == cls:
        return True
    else:
        return False

def distill_object_of_type_and_invoke_site(lhs_slot: ObjectSlot,
                                           cls: Class,
                                           invoke: Invoke) -> Iterable[InstanceObject]:
    ret = []
    for obj in lhs_slot:
        if isinstance(obj, InstanceObject) and obj.class_obj.class_ent == cls and obj.invoke == invoke:
            ret.append(obj)
    return ret

def distill_list_of_creation_site(lst_slot: ObjectSlot, expr: ast.expr) -> Iterable[IndexableObject]:
    ret = []
    for obj in lst_slot:
        if isinstance(obj, IndexableObject) and obj.expr == expr:
            ret.append(obj)
    return ret

def do_analysis(self) -> None:
    current_module = self.work_list.pop(0)
    while self.work_list:
        self.resolve_module(current_module)
        current_module = self.work_list.pop()
        already_satisfied = self.resolve_module(current_module)
        if not already_satisfied:
            # if some namespace changed, add all module depends on it to work list
            for m in current_module.get_object().depend_by:
                if m not in self.work_list:
                    self.work_list.append(m)

def do_analysis_chaotic(self) -> None:
    while True:
        all_satisfied = True
        for module in self.work_list:
            satisfied = self.resolve_module(module)
            all_satisfied = all_satisfied and satisfied
        if all_satisfied:
            break

def resolve_all(self) -> None:
    for i in range(10):
        for module in self.scene.summaries:
            self.module_object_dict[module] = module.get_object()
            self.resolve_module(module)

def resolve_rule_in_singleton_object(self, rule: Rule, obj: HeapObject) -> bool:
    if isinstance(rule, ValueFlow) and isinstance(obj, NameSpaceObject):
        return self.resolve_value_flow_namespace(rule, obj.get_namespace())
    elif isinstance(rule, Return) and isinstance(obj, FunctionObject):
        return self.resolve_return(rule, obj)
    elif isinstance(rule, AddBase):
        return self.resolve_add_base(obj, rule.cls, rule.bases)
    elif isinstance(rule, AddList):
        cls = rule.info.cls
        cls_obj: Optional[ClassObject]
        if cls is not None:
            obj_temp = self.scene.summary_map[cls].get_object()
            assert isinstance(obj_temp, ClassObject)
            cls_obj = obj_temp
        else:
            cls_obj = None
        return self.resolve_add_list(rule.lst, cls_obj, rule.expr, obj)
    else:
        assert False, f"unsupported rule type {rule.__class__}, object type {obj.__class__}"

def resolve_function(self, summary: FunctionSummary) -> None:
    for rule in summary.rules:
        self.resolve_rule_in_singleton_object(rule, summary.get_object())

def abstract_store_index(self, access_target: StoreAble, namespace: NameSpace, rhs_slot: ObjectSlot) -> bool:
    objs = self.get_store_able_value(access_target, namespace)
    return self.abstract_store_index_to_objects(objs, rhs_slot)

def abstract_store_index_to_objects(self,
                                    objs: ReadOnlyObjectSlot,
                                    rhs_slot: ReadOnlyObjectSlot) -> bool:
    already_satisfied = True
    for obj in objs:
        if isinstance(obj, IndexableObject):
            already_satisfied = already_satisfied and update_if_not_contain_all(obj.list_contents, rhs_slot)
    return already_satisfied

def resolve_return(self, rule: Return, obj: FunctionObject) -> bool:
    ret_value = self.get_store_able_value(rule.ret_value, obj.namespace)
    return update_if_not_contain_all(obj.return_slot, ret_value)

def handle_indexable_object_modify(self, func: FunctionObject, args: Sequence[ReadOnlyObjectSlot]) -> bool:
    if is_dict_update(func) and len(args) == 2:
        for container, in_coming_container in itertools.product(args[0], args[1]):
            if isinstance(container, IndexableObject) and isinstance(in_coming_container, IndexableObject):
                return update_if_not_contain_all(container.list_contents, in_coming_container.list_contents)
    elif is_list_append(func) and len(args) == 2:
        for container, new_element in itertools.product(args[0], args[1]):
            if isinstance(container, IndexableObject):
                return update_if_not_contain_all(container.list_contents, {new_element})
    return True

def call_initializer_on_instance(self, cls_obj: ClassObject, instance: HeapObject,
                                 args: Sequence[ReadOnlyObjectSlot],
                                 kwargs: Sequence[Tuple[str, ReadOnlyObjectSlot]], namespace: NameSpace) -> None:
    initializer = cls_obj.namespace["__init__"]
    first_arg: List[ReadOnlyObjectSlot] = [{instance}]
    args_slots: List[ReadOnlyObjectSlot] = first_arg + list(args)
    for obj in initializer:
        if isinstance(obj, FunctionObject):
            self.abstract_function_object_call(obj, args_slots, kwargs)

def add_all_dependencies(self, module: ModuleSummary) -> None:
    for dep in module.get_object().depend_by:
        if dep not in self.work_list:
            self.work_list.append(dep)

def resolve_add_list(self, lst: StoreAble, cls: Optional[ClassObject], expr: ast.expr, obj: HeapObject) -> bool:
    match lst:
        case VariableLocal() | Temporary() | ParameterLocal() as v:
            lhs_slot = obj.namespace[v.name()]
            if distill_list_of_creation_site(lhs_slot, expr):
                return True
            else:
                lst_instance = IndexableObject(cls, expr)
                return update_if_not_contain_all(lhs_slot, [lst_instance])
        case _:
            return True

def get_const_object(self, store: StoreAble) -> HeapObject:
    match store:
        case FuncConst() as fc:
            return self.scene.summary_map[fc.func].get_object()
        case ClassConst() as cc:
            return self.scene.summary_map[cc.cls].get_object()
        case ModuleConst() as m:
            return self.scene.summary_map[m.mod].get_object()
        case _:
            raise NotImplementedError

def get_store_able_value(self, store: StoreAble, namespace: NameSpace) -> Iterable[HeapObject]:
    match store:
        case VariableLocal() | Temporary() | ParameterLocal() as v:
            return namespace[v.name()]
        case VariableOuter() as v:
            return self.scene.summary_map[v.scope].get_namespace()[v.name()]
        case FuncConst() as fc:
            return {self.get_const_object(fc)}
        case ClassConst() as cc:
            return {self.get_const_object(cc)}
        case FieldAccess() as field_access:
            return self.abstract_load(field_access, namespace)
        case ModuleConst() as m:
            if not isinstance(m.mod, UnknownModule):
                # todo: build model for unknown module
                return {self.get_const_object(m)}
            else:
                return set()
        case PackageConst() as p:
            return set()
            # todo: implement package object
            return {self.get_const_object(p)}
        case ClassAttributeAccess() as class_attribute_access:
            return self.get_class_attribute(class_attribute_access)
        case Constant():
            return set()
        case IndexAccess() as index_access:
            return self.abstract_load_index(index_access, namespace)
        case _:
            raise NotImplementedError(f"{store.__class__.__name__}")

def abstract_load_index(self, index_access: IndexAccess, namespace: NameSpace) -> Iterable[HeapObject]:
    target_slot = self.get_store_able_value(index_access.target, namespace)
    return self.get_index_of_object_slot(target_slot)

def get_index_of_object_slot(self, obj_slot: ReadOnlyObjectSlot) -> ReadOnlyObjectSlot:
    ret = set()
    for obj in obj_slot:
        if isinstance(obj, IndexableObject):
            ret.update(obj.list_contents)
        elif isinstance(obj, InstanceObject):
            next_methods: "ObjectSlot" = set()
            obj.get_member("__next__", next_methods)
            for method in next_methods:
                if isinstance(method, InstanceMethodReference):
                    ret.update(self.abstract_function_object_call(method.func_obj, [[obj]], []))
            iter_methods: "ObjectSlot" = set()
            obj.get_member("__iter__", iter_methods)
            for method in iter_methods:
                if isinstance(method, InstanceMethodReference):
                    self.abstract_function_object_call(method.func_obj, [[obj]], [])
    return ret

def _get_define_entities(self, ent_longname: EntLongname, ent_name: str) -> ty.List[Entity]:
    ret: ty.List[Entity] = []
    for ent_1 in self.ents:
        if ent_1.longname == ent_longname:
            refs = ent_1.refs()
            for ref in refs:
                if ref.ref_kind == RefKind.DefineKind and ref.target_ent.longname.name == ent_name:
                    ret.append(ref.target_ent)

    return ret

def remove(self, target: Entity) -> None:
    try:
        self.ents.remove(target)
    except ValueError:
        pass

def __eq__(self, other: object) -> bool:
    if isinstance(other, EntLongname) and len(other._scope) == len(self._scope):
        for lhs, rhs in zip(self._scope, other._scope):
            if lhs != rhs:
                return False
        return True
    return False

def offset(self, offset: int) -> None:
    assert self.end_col == -1
    self.start_col += offset

def get_syntactic_head(tree: ast.AST) -> Span:
    start_line = tree.lineno
    end_line = -1
    start_col = tree.col_offset
    end_col = -1
    return Span(start_line, end_line, start_col, end_col)

def append(self, name: str, new_span: Span, new_path: Optional[Path]) -> "Location":
    if new_path is None:
        new_path = self._file_path
    return Location(new_path, new_span, self._scope + [name])

def __eq__(self, other: object) -> bool:
    if isinstance(other, Location) and len(other._scope) == len(self._scope):
        for lhs, rhs in zip(self._scope, other._scope):
            if lhs != rhs:
                return False
        return True
    return False

def add_ref(self, ref: "Ref") -> None:
    # todo: should we remove reference with same representation?
    if ref not in self._refs:
        self._refs.append(ref)

def __eq__(self, other: object) -> bool:
    if isinstance(other, self.__class__):
        return other.longname == self.longname and other.location == self.location
    return False

def direct_type(self) -> "ValueInfo":
    from enre.analysis.value_info import ValueInfo
    return ValueInfo.get_any()

def __init__(self, scope: Entity, longname: EntLongname, location: Location):
    self.scope = scope
    super().__init__(longname, location)

def add_ref(self, ref: "Ref") -> None:
    if ref.ref_kind == RefKind.ContainKind:
        self._names[ref.target_ent.longname.name].append(ref.target_ent)
    super(Package, self).add_ref(ref)

def add_ref(self, ref: "Ref") -> None:
    if ref.ref_kind == RefKind.DefineKind:
        self._names[ref.target_ent.longname.name].append(ref.target_ent)
    super(Module, self).add_ref(ref)

def add_ref(self, ref: "Ref") -> None:
    if ref.ref_kind == RefKind.DefineKind:
        self._names[ref.target_ent.longname.name].append(ref.target_ent)
    super(BuiltinModule, self).add_ref(ref)

def direct_type(self) -> "ValueInfo":
    if len(self.possible_target_ent) == 1:
        return self.possible_target_ent[0].direct_type()
    else:
        return ValueInfo.get_any()

def _build_alias_deps(self) -> None:
    from enre.ref.Ref import Ref
    for ent in self.possible_target_ent:
        alias_span = self.location.code_span
        self.add_ref(Ref(RefKind.AliasTo, ent, alias_span.start_line, alias_span.end_line, False, None))

def names(self) -> "NamespaceType":
    # class scope, name to possible bound entities
    return self._names

def get_attribute(self, attr: str) -> List[Entity]:
    current_class_attrs = self.names[attr]
    if current_class_attrs:
        return current_class_attrs
    for cls_ent in self.inherits:
        inherited_attrs = cls_ent.get_attribute(attr)
        if inherited_attrs:
            return inherited_attrs
    return []

def add_ref(self, ref: "Ref") -> None:
    if ref.ref_kind == RefKind.DefineKind:
        self._names[ref.target_ent.longname.name].append(ref.target_ent)
    elif ref.ref_kind == RefKind.InheritKind:
        if isinstance(ref.target_ent, Class):
            self._inherits.append(ref.target_ent)
    super(Class, self).add_ref(ref)

def implement_method(self, longname: EntLongname) -> bool:
    method_name = longname.name
    for name, ents in self._names.items():
        if name == method_name:
            for entity in ents:
                if isinstance(entity, Function):
                    if entity.abstract_kind:
                        return False
                    else:
                        return True
    return False

def __init__(self, name: str, loc: Optional[Location] = None):
    if loc is None:
        loc = Location()
    super(UnknownVar, self).__init__(EntLongname([name]), loc)

def get_unknown_var(cls, name: str) -> "UnknownVar":
    if name in cls._unknown_pool.keys():
        return cls._unknown_pool[name]
    else:
        unknown_var = UnknownVar(name)
        cls._unknown_pool[name] = unknown_var
        return unknown_var

def __init__(self, scope: Entity, longname: EntLongname, location: Location):
    self.scope = scope
    super(Parameter, self).__init__(longname, location)

def __init__(self, class_ent: Class, longname: EntLongname, location: Location):
    self.class_ent: Class = class_ent
    super(ClassAttribute, self).__init__(longname, location)

def __init__(self, longname: EntLongname, location: Location, receiver_type: "ValueInfo") -> None:
    self.receiver_type = receiver_type
    super(UnresolvedAttribute, self).__init__(longname, location)

def get_file_level_ent(m: Entity, name: str) -> List[Entity]:
    ret = []
    for ref in m.refs():
        if ref.ref_kind == RefKind.DefineKind or ref.ref_kind == RefKind.ContainKind:
            if ref.target_ent.longname.name == name or name == "*":
                ret.append(ref.target_ent)
    return ret

def get_target_ent(heap_obj: "HeapObject") -> Optional[Entity]:
    if isinstance(heap_obj, ModuleObject):
        return heap_obj.module_ent
    elif isinstance(heap_obj, FunctionObject):
        return heap_obj.func_ent
    elif isinstance(heap_obj, ClassObject):
        return heap_obj.class_ent
    elif isinstance(heap_obj, InstanceMethodReference):
        return heap_obj.func_obj.func_ent
    else:
        return None

def aggregate_cfg_info(root_db: "RootDB", resolver: "Resolver") -> None:
    print("aggregating cfg result to dependency")
    for file_path, module_db in root_db.tree.items():
        for ent in module_db.dep_db.ents:
            aggregated_expr = set()
            if ent in resolver.scene.summary_map:
                summary = resolver.scene.summary_map[ent]
                for ref in ent.refs():
                    if ref.ref_kind in [RefKind.CallKind, RefKind.UseKind]:
                        invoke_expr = ref.expr
                        if invoke_expr is not None and invoke_expr in summary.get_syntax_namespace():
                            aggregated_expr.add(invoke_expr)
                            name = summary.get_syntax_namespace()[invoke_expr]
                            resolved_objs = summary.get_object().namespace[name]
                            ref.resolved_targets.update(map_resolved_objs(resolved_objs))

                    if isinstance(ent, Class) and ref.ref_kind == RefKind.InheritKind:
                        assert isinstance(summary, ClassSummary)
                        ref.resolved_targets.update(map_resolved_objs(summary.get_object().inherits))

                for invoke in summary.get_invokes():
                    if not invoke.expr in aggregated_expr:
                        invoke_targets = resolver.get_store_able_value(invoke.target, summary.get_namespace())
                        for target in invoke_targets:
                            target_func: Function
                            if isinstance(target, FunctionObject):
                                target_func = target.func_ent
                            elif isinstance(target, InstanceMethodReference):
                                target_func = target.func_obj.func_ent
                            else:
                                continue
                            invoke_expr = invoke.expr
                            ent.add_ref(
                                Ref(RefKind.CallKind, target_func, invoke_expr.lineno, invoke_expr.col_offset, False, invoke_expr,
                                    set()))

def build_attr_map(self) -> Dict[str, List[Entity]]:
    """
    :return: the attribute map which map attribute name to the
        attribute entities
    """
    attr_map: Dict[str, List[Entity]] = defaultdict(list)
    for _, module_db in self.package_db.tree.items():
        for ent in module_db.dep_db.ents:
            if isinstance(ent, Class):
                for attr_name, attr_ent in ent.names.items():
                    attr_map[attr_name].extend(attr_ent)
    return attr_map

def resolve_referenced_attr(self, attr_map: Dict[str, List[Entity]],
                            ambiguous_ent_dict: Dict[str, Optional[AmbiguousAttribute]]) -> None:
    for _, module_db in self.package_db.tree.items():
        for ent in module_db.dep_db.ents:
            for ref in ent.refs():
                self.rebuild_ref(ent, ref, attr_map, ambiguous_ent_dict)

def build_ambiguous_ents(self, ambiguous_dict: Dict[str, List[Entity]]) -> Dict[str, Optional[AmbiguousAttribute]]:
    ambiguous_ents_dict: Dict[str, Optional[AmbiguousAttribute]] = defaultdict(lambda: None)
    for name, ents in ambiguous_dict.items():
        ambiguous_ent = AmbiguousAttribute(name)
        ambiguous_ents_dict[name] = ambiguous_ent
        self._package_db.global_db.add_ent(ambiguous_ent)
        for tar_ent in ents:
            tar_ent.add_ref(Ref(RefKind.HasambiguousKind, ambiguous_ent, -1, -1, False, None))
    return ambiguous_ents_dict

def work_flow(self) -> None:
    for _, module_db in self._package_db.tree.items():
        for ent in module_db.dep_db.ents:
            if isinstance(ent, Class):
                # 私有变量正则匹配式
                private_attr_regular = re.compile("^_[A-Za-z0-9]+$")
                abstract_info: AbstractClassInfo = AbstractClassInfo()
                flag = False
                for name, ents in ent.names.items():
                    for entity in ents:
                        if isinstance(entity, Function):
                            if entity.abstract_kind:
                                # handle abstract_method
                                abstract_info.abstract_methods.append(entity)
                                flag = True
                            elif entity.readonly_property_name:
                                # handle readonly property
                                if entity.readonly_property_name in ent.names:
                                    for attr_ent in ent.get_attribute(entity.readonly_property_name):
                                        if isinstance(attr_ent, Function):
                                            ent.readonly_attribute[entity.readonly_property_name].append(
                                                attr_ent)
                        elif isinstance(entity, ClassAttribute) and private_attr_regular.match(name):
                            # handle private attribute
                            ent.private_attribute[name].append(entity)

                # todo: 目前对于内部类的继承通过_refs分析，完成之后注释掉这个for，取消注释下面for循环的第一个if
                for ref in ent._refs:
                    if ref.ref_kind == RefKind.InheritKind:
                        if ref.target_ent.longname.name == 'ABC':
                            abstract_info.inherit = "ABC"
                            flag = True

                for parent_class in ent.inherits:
                    # if parent_class.longname.name == 'ABC':
                    #     # 分析是否直接继承ABC类
                    #     abstract_info.inherit = "ABC"
                    #     flag = True
                    if parent_class.abstract_info:
                        # 分析是否包含抽象类方法，以及是否完全实现了父类的抽象方法
                        for abstract_method in parent_class.abstract_info.abstract_methods:
                            if abstract_method.abstract_kind == FunctionKind.AbstractMethod:
                                # 不分析构造函数，只分析普通函数
                                if not ent.implement_method(abstract_method.longname):
                                    abstract_info.abstract_methods.append(abstract_method)
                                    flag = True

                ent.abstract_info = abstract_info if flag else None

def build_attribute_dict(self) -> None:
    for _, module_db in self.package_db.tree.items():
        for ent in module_db.dep_db.ents:
            for ref in ent.refs():
                if ref.ref_kind == RefKind.DefineKind:
                    self.attribute_dict[ref.target_ent.longname.name].append(ref.target_ent)

def __init__(self) -> None:
    self.node_list: List[NodeTy] = []
    self.edge_list: List[EdgeTy] = []

def to_json(self, is_neg: bool) -> DepTy:
    ret = dict()
    entities = []
    dependencies = []
    for n in self.node_list:
        entities.append(n)
    for e in self.edge_list:
        dependencies.append(e)
    if is_neg:
        ret["Negative Entities"] = entities
        ret["Negative Dependencies"] = dependencies
    else:
        ret["Entities"] = entities
        ret["Dependencies"] = dependencies
    return ret

def write_dependencies(self, dep: DepRepr, neg_dep: DepRepr, bind: Bind) -> None:
    for line in self.comment_lines:
        interp_line(line, dep, neg_dep, bind, self.related_line)

def read_comment_block(lines: Sequence[str], start_lineno: int) -> Tuple[List[str], int]:
    comment_lines: List[str] = []
    new_lineno = start_lineno
    for offset, line in enumerate(lines[start_lineno:]):
        if str.lstrip(line).startswith("#"):
            match_result = re.match(CommentPattern, line)
            assert match_result
            comment_line = match_result[1]
            comment_lines.append(comment_line)
        elif not str.isspace(line):
            new_lineno = start_lineno + offset
            break

    return comment_lines, new_lineno

def gen_test_case_for(file_path: Path) -> Tuple[DepRepr, DepRepr]:
    dep = DepRepr()
    neg_dep = DepRepr()
    bind: Bind = {}
    comment_blocks = build_comment_blocks(file_path)
    for block in comment_blocks:
        block.write_dependencies(dep, neg_dep, bind)
    return dep, neg_dep

def dump_meta_data(dep: DepRepr, neg_dep: DepRepr, ent_count: Dict[str, int], dep_count: Dict[str, int]) -> None:
    for node in dep.node_list:
        ent_count["all entity"] += 1
        ent_count[node["ent_type"]] += 1

    for edge in dep.edge_list:
        dep_count["all dependency"] += 1
        dep_count[edge["kind"]] += 1

def gen_test_case_dir(dir: Path) -> None:
    test_case_dep_meta_data: Dict[str, int] = defaultdict(int)
    test_case_ent_meta_data: Dict[str, int] = defaultdict(int)
    for file_path in dir.iterdir():
        if file_path.name.endswith(".py"):
            test_case_name = file_path.name.removesuffix(".py")
            dep, neg_dep = gen_test_case_for(file_path)
            dump_meta_data(dep, neg_dep, test_case_ent_meta_data, test_case_dep_meta_data)
            with open(f"{test_case_name}.json", "w") as file:
                json.dump(merge_two_dicts(dep.to_json(False), neg_dep.to_json(True)), file, indent=4)

    with open("test_case_meta_data.json", "w") as file:
        meta_data = {"Entity": test_case_ent_meta_data, "Dependency": test_case_dep_meta_data}
        json.dump(meta_data, file, indent=4)

def json_entity_list_to_yaml(ent_list: List[dict], is_neg: bool) -> List[dict]:
    ret = []
    for e in ent_list:
        ret.append(json_entity_dict_to_yaml(e, is_neg))
    return ret

def json_dep_list_to_yaml(deps: List[dict], is_neg: bool) -> list:
    ret = []
    for d in deps:
        ret.append(json_dep_dict_to_yaml(d, is_neg))
    return ret

