def init_statistic(self) -> None:
    for node in self.node_list:
        node_kind = node["ent_type"]
        self.node_statistic[node_kind] += 1

    for edge in self.edge_list:
        edge_kind = edge["kind"]
        self.edge_statistic[edge_kind] += 1

def diff_nodes(self) -> List[NodeTy]:
    if self._diff_nodes is not None:
        return self._diff_nodes
    diff_node_list: List[NodeTy] = []
    length = len(self.tar_graph.node_list)
    for index, node in enumerate(self.tar_graph.node_list):
        print(f"processing: {index}/{length}")
        matched_node = first_match(self.base_graph.node_list,
                                   lambda n: self._mapping.is_same_node(n, node))
        if matched_node is None:
            diff_node_list.append(node)

    return diff_node_list

def diff_edges(self) -> List[EdgeTy]:
    if self._diff_edges is not None:
        return self._diff_edges
    diff_edge_list: List[EdgeTy] = []
    length = len(self.tar_graph.edge_list)
    for index, edge in enumerate(self.tar_graph.edge_list):
        print(f"processing: {index}/{length}")

        matched_edge = first_match(self.base_graph.edge_list,
                                   lambda e: self._mapping.is_same_edge(e, edge))
        if matched_edge is None:
            diff_edge_list.append(edge)
    return diff_edge_list

def diff_statistic(self) -> Tuple[Dict[str, int], Dict[str, int]]:
    diff_node_statistic: Dict[str, int] = defaultdict(int)
    diff_edge_statistic: Dict[str, int] = defaultdict(int)
    for node in self.diff_nodes():
        diff_node_statistic[node["ent_type"]] += 1
    for edge in self.diff_edges():
        diff_edge_statistic[edge["kind"]] += 1
    self._diff_ent_statistic = diff_node_statistic
    self._diff_dep_statistic = diff_edge_statistic
    return diff_node_statistic, diff_edge_statistic

def dump_statistic(self, fp: IO[str]) -> None:
    import csv
    writer = csv.writer(fp)

def __init__(self) -> None:
    self._node_list: List[Node] = []
    self._edge_list: List[Edge] = []

def to_json_1(self) -> JsonDict:
    ret: JsonDict = {"variables": [], "cells": []}
    for n in self._node_list:
        variable = {"id": n.id, "qualifiedName": n.longname, "category": n.ent_type,
                    "location": {"startLine": n.start_line, "endLine": n.end_line,
                                 "startColumn": n.start_col, "endColumn": n.end_col}}
        if n.file_path != ".":
            variable["File"] = n.file_path
        if exist_no_empty(n.modifiers):
            variable["modifiers"] = n.modifiers
        ret["variables"].append(variable)
    for e in self._edge_list:
        values: JsonDict = {"kind": e.kind, "in_type_context": e.in_type_ctx}
        location = {"startLine": e.lineno, "startCol": e.col_offset}
        if e.resolved_targets:
            values["resolved"] = e.resolved_targets
        ret["cells"].append({"src": e.src,
                             "dest": e.dest,
                             "values": values,
                             "location": location})
    return ret

def from_package_db(cls, package_db: RootDB) -> "DepRepr":
    dep_repr = DepRepr()
    for rel_path, module_db in package_db.tree.items():
        for ent in module_db.dep_db.ents:
            cls.write_ent_repr(ent, dep_repr)
    for ent in package_db.global_db.ents:
        cls.write_ent_repr(ent, dep_repr)
    return dep_repr

def get_modifiers(cls, ent: Entity) -> Dict[str, list[str]]:
    ret: Dict[str, List[str]] = {}
    if isinstance(ent, Class):
        ret = {
            'modifier': [],
            'readonlyProperty': [],
            'privateProperty': []
        }
        if ent.abstract_info:
            ret['modifier'].append('abstract class')
        for name, _ in ent.readonly_attribute.items():
            ret['readonlyProperty'].append(name)
        for name, _ in ent.private_attribute.items():
            ret['privateProperty'].append(name)
    elif isinstance(ent, Function):
        ret = {
            'modifier': []
        }
        if ent.abstract_kind == FunctionKind.AbstractMethod:
            ret['modifier'].append('abstract method')
        if ent.static_kind == FunctionKind.StaticMethod:
            ret['modifier'].append('static method')
    return ret

def from_summaries(summaries: Sequence[ModuleSummary]) -> str:
    ret = ""
    for summary in summaries:
        ret += f"{str(summary)}\n"
        for name, objs in summary.get_namespace().items():
            ret += f"\t{name}: "
            ret += ",".join(str(obj.representation()) for obj in objs)
            ret += "\n"

    return ret

def call_graph_representation(resolver: Resolver) -> Dict[str, Any]:
    call_graph_dict = defaultdict(list)
    call_graph = resolver.call_graph
    for source, invoke_targets in call_graph.graph.items():
        for target in invoke_targets:
            if isinstance(target, Class) and "builtins" not in target.longname.longname:
                continue
            call_graph_dict[source.longname.longname].append(target.longname.longname)
    return call_graph_dict

def get_node_by_id(id_num: int, node_dict: Dict[int, NodeTy]) -> NodeTy:
    return node_dict[id_num]
    raise Exception(f"not included id {id_num}")

def is_same_node(self, base_node: NodeTy, und_node: NodeTy) -> bool:
    und_node_kind = und_node["ent_type"]
    base_node_kind = base_node["ent_type"]
    if und_node_kind not in ENTMAPPING:
        return False
    if ENTMAPPING[und_node_kind] == []:
        # for ignoring specific kind of entity
        return True

    if base_node_kind not in ENTMAPPING[und_node_kind]:
        return False
    if und_node_kind in ["Module File", "File"]:
        rel_path = Path(und_node["longname"]).relative_to(self._root_dir.parent.resolve())
        new_longname = ".".join((str(rel_path).replace(".py", "")).split(os.sep))
        return new_longname == base_node["longname"]
    elif und_node_kind in ["LambdaParameter"]:
        base_new_longname = base_node["longname"]
        und_name = und_node["longname"]
        if "\\" in und_name:
            rel_path = Path(und_name).relative_to(self._root_dir.parent.resolve())
            und_name = ".".join((str(rel_path).replace(".py", "")).split(os.sep))
        return und_name == re.sub(r".\(\d+\)", "", base_new_longname)
    else:
        return und_node["longname"] == base_node["longname"]

def initialize_node_dict(self) -> None:
    for node in self._node_list:
        self._node_dict[node["id"]] = node

    for node in self._und_node_list:
        self._und_node_dict[node["id"]] = node

def extract_method_code(file_path: str, start_line: int, end_line: int, project_root: Path = None) -> str:
    """从文件中提取指定行号的代码"""
    if start_line <= 0:
        return ""

    try:
        # 尝试多种路径解析方式
        path = None
        tried_paths = []

        # 1. 尝试直接路径（绝对路径或相对当前目录）
        test_path = Path(file_path)
        tried_paths.append(str(test_path.absolute()))
        if test_path.exists():
            path = test_path

        # 2. 尝试相对于项目根目录的路径
        if not path and project_root:
            potential_path = project_root / file_path
            tried_paths.append(str(potential_path.absolute()))
            if potential_path.exists():
                path = potential_path

        # 3. 尝试标准化路径分隔符
        if not path and project_root:
            # 根据项目根目录的路径分隔符来标准化
            if "\\" in str(project_root):
                normalized_path = file_path.replace("/", "\\")
            else:
                normalized_path = file_path.replace("\\", "/")
            potential_path = project_root / normalized_path
            tried_paths.append(str(potential_path.absolute()))
            if potential_path.exists():
                path = potential_path

        if not path or not path.exists():
            # 如果所有路径都失败，尝试查找文件（不区分大小写）
            if project_root:
                file_name = Path(file_path).name
                for py_file in project_root.rglob("*.py"):
                    if py_file.name.lower() == file_name.lower():
                        # 检查路径是否匹配（忽略大小写和路径分隔符）
                        rel_path = str(py_file.relative_to(project_root)).replace("\\", "/")
                        if rel_path.lower() == file_path.lower().replace("\\", "/"):
                            path = py_file
                            break

        if not path or not path.exists():
            # 如果文件不存在，可能是因为文件路径是相对于分析时的项目根目录的
            # 尝试在项目根目录下递归查找文件名匹配的文件
            if project_root and project_root.exists():
                file_name = Path(file_path).name
                # 只在项目根目录下查找，避免搜索整个系统
                for py_file in project_root.rglob(file_name):
                    # 检查相对路径是否匹配（忽略大小写和路径分隔符）
                    rel_path = str(py_file.relative_to(project_root)).replace("\\", "/")
                    expected_rel_path = file_path.replace("\\", "/")
                    if rel_path.lower() == expected_rel_path.lower():
                        path = py_file
                        break

                # 如果还是找不到，尝试只匹配文件名
                if (not path or not path.exists()) and file_name:
                    for py_file in project_root.rglob(file_name):
                        path = py_file
                        break

            if not path or not path.exists():
                return ""

        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()
            if start_line > len(lines):
                return ""

            # 如果 end_line 无效（<=0 或 -1），尝试提取到函数结束
            # 首先尝试找到函数的结束位置（通过查找下一个相同或更小缩进的非空行）
            if end_line <= 0 or end_line > len(lines):
                # 如果没有有效的 end_line，尝试从 start_line 开始找到函数的结束
                # 获取函数定义行的缩进
                if start_line <= len(lines):
                    def_line = lines[start_line - 1]
                    # 计算缩进（假设使用空格或制表符）
                    indent_level = len(def_line) - len(def_line.lstrip())

                    # 从下一行开始查找，直到找到相同或更小缩进的非空行
                    end_line = start_line
                    for i in range(start_line, len(lines)):
                        line = lines[i]
                        if line.strip():  # 非空行
                            line_indent = len(line) - len(line.lstrip())
                            if line_indent <= indent_level:
                                end_line = i  # 找到函数结束，但不包括这一行
                                break
                    else:
                        # 如果没找到，就提取到文件末尾
                        end_line = len(lines)

            # 确保 end_line 在有效范围内
            if end_line > len(lines):
                end_line = len(lines)
            if end_line < start_line:
                end_line = start_line

            # Python 行号从1开始，数组索引从0开始
            code_lines = lines[start_line - 1:end_line]
            return "".join(code_lines).rstrip()
    except Exception as e:
        # 调试：可以取消注释来查看错误
        # print(f"Error extracting code from {file_path}: {e}")
        return ""

def extract_method_code_from_entity(node, package_db, project_root: Path = None) -> str:
    """从原始 Entity 中尝试提取方法代码（优先方法）"""
    from enre.ent.EntKind import EntKind

    # 尝试从 package_db 中找到对应的 Entity
    func_entity = None
    for rel_path, module_db in package_db.tree.items():
        for ent in module_db.dep_db.ents:
            if ent.id == node.id and ent.kind() == EntKind.Function:
                func_entity = ent
                break
        if func_entity:
            break

    if not func_entity:
        # 如果找不到，也尝试全局数据库
        for ent in package_db.global_db.ents:
            if ent.id == node.id and ent.kind() == EntKind.Function:
                func_entity = ent
                break

    if not func_entity:
        return ""

    # 使用 Entity 的位置信息（更准确）
    try:
        file_path = str(func_entity.location.file_path)
        # 确保路径使用正斜杠（与 Node 中的格式一致）
        file_path = file_path.replace("\\", "/")
        start_line = func_entity.location.code_span.start_line
        end_line = func_entity.location.code_span.end_line

        # 如果 Entity 的路径是绝对路径，尝试使用它
        code = extract_method_code(file_path, start_line, end_line, project_root)

        # 如果提取失败，尝试使用相对路径（从 Node 中获取）
        if not code and node.file_path != file_path:
            code = extract_method_code(node.file_path, start_line, end_line, project_root)

        return code
    except Exception:
        # 如果访问 Entity 位置信息失败，回退到使用 Node 的信息
        return extract_method_code(node.file_path, node.start_line, node.end_line, project_root)

def extract_method_code_direct(node, package_db, project_root: Path = None) -> str:
    """直接从 package_db 中查找文件并提取代码"""
    from enre.ent.EntKind import EntKind

    # 尝试从 package_db 中找到对应的 Entity
    func_entity = None
    for rel_path, module_db in package_db.tree.items():
        for ent in module_db.dep_db.ents:
            if ent.id == node.id and ent.kind() == EntKind.Function:
                func_entity = ent
                # 同时获取模块的路径信息
                module_path = rel_path
                break
        if func_entity:
            break

    if not func_entity:
        return ""

    # 尝试多种文件路径
    file_paths_to_try = []

    # 1. 使用 Entity 的 file_path
    try:
        file_paths_to_try.append(str(func_entity.location.file_path))
    except:
        pass

    # 2. 使用 Node 的 file_path
    file_paths_to_try.append(node.file_path)

    # 3. 尝试使用模块路径 + 文件名
    try:
        if module_path:
            file_name = Path(node.file_path).name
            file_paths_to_try.append(str(module_path / file_name))
    except:
        pass

    # 4. 尝试使用项目根目录 + 相对路径
    if project_root:
        file_paths_to_try.append(str(project_root / node.file_path))

    start_line = func_entity.location.code_span.start_line
    end_line = func_entity.location.code_span.end_line

    # 如果 Entity 的行号无效，使用 Node 的行号
    if start_line <= 0:
        start_line = node.start_line
    if end_line <= 0:
        end_line = node.end_line

    # 尝试每个可能的路径
    for file_path in file_paths_to_try:
        if file_path:
            code = extract_method_code(file_path, start_line, end_line, project_root)
            if code:
                return code

    return ""

def get_function_signature_with_params(node, package_db) -> str:
    """获取包含参数信息的函数签名"""
    from enre.ent.EntKind import EntKind, RefKind

    # 首先尝试从 package_db 中找到对应的 Entity
    func_entity = None
    for rel_path, module_db in package_db.tree.items():
        for ent in module_db.dep_db.ents:
            if ent.id == node.id and ent.kind() == EntKind.Function:
                func_entity = ent
                break
        if func_entity:
            break

    if not func_entity:
        # 如果找不到，也尝试全局数据库
        for ent in package_db.global_db.ents:
            if ent.id == node.id and ent.kind() == EntKind.Function:
                func_entity = ent
                break

    if not func_entity:
        # 如果找不到 Entity，返回原始 longname
        return node.longname

    # 从 Entity 的 refs 中查找参数（DefineKind 的 Parameter 类型）
    params = []
    for ref in func_entity.refs():
        if (ref.ref_kind == RefKind.DefineKind and 
            ref.target_ent.kind() == EntKind.Parameter):
            # 参数名称从 longname 中提取（通常是 function_name.param_name）
            param_name = ref.target_ent.longname.name
            params.append((ref.lineno, ref.col_offset, param_name))

    # 按行号和列号排序参数（保持它们在源代码中的顺序）
    params.sort(key=lambda x: (x[0], x[1]))
    param_names = [p[2] for p in params]

    # 构建带参数的签名
    if param_names:
        return f"{node.longname}({', '.join(param_names)})"
    else:
        return f"{node.longname}()"

def normalize_01(M, eps=1e-12):
    M = symmetrize_zero_diag(M)
    mmin, mmax = M.min(), M.max()
    if mmax - mmin < eps:
        return np.zeros_like(M)
    M = (M - mmin) / (mmax - mmin)
    np.fill_diagonal(M, 0.0)
    return M

def fuse_weights(A, S, a=0.5):
    A_ = normalize_01(A)
    S_ = normalize_01(S)
    W = a * S_ + (1 - a) * A_
    return symmetrize_zero_diag(W)

def sparsify_threshold(W, tau=None):
    """
    按阈值稀疏化：权重 < tau 的边置 0。tau=None 表示不启用。
    """
    if tau is None or tau <= 0:
        return symmetrize_zero_diag(W)
    W2 = W.copy()
    W2[W2 < tau] = 0.0
    return symmetrize_zero_diag(W2)

def build_igraph_from_W(W):
    W = symmetrize_zero_diag(W)
    return ig.Graph.Weighted_Adjacency(W.tolist(), mode=ig.ADJ_UNDIRECTED, attr='weight', loops=False)

def pairwise_mean_ari(partitions):
    if len(partitions) <= 1:
        return 1.0
    ARIs = []
    for i in range(len(partitions)):
        for j in range(i+1, len(partitions)):
            ARIs.append(adjusted_rand_score(partitions[i], partitions[j]))
    return float(np.mean(ARIs))

def safe_silhouette_from_similarity(W, labels, use_silhouette=False, sample_size=None, rng=42):
    """
    可选计算 silhouette（使用距离 1-W）。默认关闭以避免误用非度量距离。
    """
    if not use_silhouette:
        return None
    n = W.shape[0]
    dist = 1.0 - np.clip(W, 0.0, 1.0)
    np.fill_diagonal(dist, 0.0)
    labels = np.asarray(labels)
    # 至少要有 2 个簇且每个簇 >= 2
    uniq, counts = np.unique(labels, return_counts=True)
    if uniq.size < 2 or np.any(counts < 2):
        return None
    if sample_size is not None and sample_size < n:
        rng = np.random.default_rng(rng)
        idx = rng.choice(n, size=sample_size, replace=False)
        dist = dist[np.ix_(idx, idx)]
        labels = labels[idx]
    try:
        return float(silhouette_score(dist, labels, metric="precomputed"))
    except Exception:
        return None

def call_with_retry(fn, retries=5, base_delay=0.5, max_delay=8.0):
    for i in range(retries):
        try:
            return fn()
        except Exception as e:
            msg = str(e)
            if "429" not in msg and "RateLimit" not in msg and "upstream" not in msg:
                raise
            delay = min(max_delay, base_delay * (2 ** i)) * (1 + random.random() * 0.25)
            time.sleep(delay)
    return fn()

def normalize_to_str(value: Any) -> str:
    """将可能为 str/dict/list/其他 的值规范化为多行字符串"""
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, dict):
        lines = []
        for k, v in value.items():
            k_str = str(k).strip()
            v_str = normalize_to_str(v)
            if k_str and v_str:
                lines.append(f"- {k_str}: {v_str}")
            elif k_str:
                lines.append(f"- {k_str}")
            elif v_str:
                lines.append(f"- {v_str}")
        return "\n".join(lines)
    if isinstance(value, list):
        lines = []
        for item in value:
            item_str = normalize_to_str(item)
            for line in (item_str.splitlines() or [""]):
                line = line.strip()
                if not line:
                    continue
                if line.startswith("- "):
                    lines.append(line)
                else:
                    lines.append(f"- {line}")
        return "\n".join(lines)
    return str(value).strip()

def clean_json_text(text: str) -> str:
    txt = text.strip()
    txt = txt.replace("```json", "```")
    if txt.startswith("```") and txt.endswith("```"):
        txt = txt[3:-3].strip()

    start = txt.find("{")
    if start == -1:
        return txt
    depth = 0
    end = -1
    for i, ch in enumerate(txt[start:], start=start):
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                end = i
                break
    if end != -1:
        return txt[start:end+1].strip()
    return txt[start:].strip()

def parse_usecase_payload(json_str: str) -> Dict[str, Any]:
    raw = clean_json_text(json_str)
    data = json.loads(raw)

    if "description" in data and not isinstance(data["description"], str):
        data["description"] = normalize_to_str(data["description"])
    if "flow" in data and not isinstance(data["flow"], str):
        data["flow"] = normalize_to_str(data["flow"])
    if "notf" in data and not isinstance(data["notf"], str):
        data["notf"] = normalize_to_str(data["notf"])

    data.setdefault("description", "")
    data.setdefault("flow", "")
    data.setdefault("notf", "")

    return data

def merge_features_by_method_cluster(features: List[Feature], method_clusters: List[method_Cluster], modelname: str):
    merged_features_des = []
    for method_cluster in method_clusters:
        related_features = [f for f in features if f.cluster_id == method_cluster.cluster_id]
        feature_list = ""
        for i, feature in enumerate(related_features):
            feature_list += f"{i+1}. {feature.feature_desc}\n"
        module_list = ""
        for i, merged_feature_des in enumerate(merged_features_des):
            module_list += f"{i+1}. {merged_feature_des}\n"
        prompt = merge_userstory_prompt.format(
            feature_list=feature_list,
            module_list=module_list
        )
        try:
            response = call_with_retry(lambda: get_client().chat.completions.create(
                messages=[{"role": "user", "content": prompt}],
                model=modelname,
                response_format={"type": "json_object"},
                temperature=0.3,
                top_p=0.95,
                frequency_penalty=0.5,
                presence_penalty=0.2
            ))
            json_str = response.choices[0].message.content
            json_str = json_str.replace("```json", "").replace("```", "")
            result_dict = json.loads(json_str)
            if "description" not in result_dict and isinstance(result_dict, dict):
                result_dict = {"description": next(iter(result_dict.values()))}
            result = module.model_validate(result_dict)
            merged_features_des.append(result.description)
            method_cluster.cluster_desc = result.description
        except json.JSONDecodeError as e:
            print(f"JSON解析失败: {e}")
        except ValidationError as e:
            print(f"Pydantic验证失败: {e}")
        except Exception as e:
            print(f"其他错误: {e}")
        print(f"Module ID: {method_cluster.cluster_id}, Description: {method_cluster.cluster_desc}\n")

def save_to_file_cluster(files, best_labels):
    file_clusters = {}
    for i, file in enumerate(files):
        if best_labels[i] not in file_clusters:
            file_clusters[best_labels[i]] = file_Cluster(best_labels[i], "", [])
        file_clusters[best_labels[i]].cluster_file_list.append(file)
    return file_clusters.values()

def minmax(xs):
    xs = np.array(xs, dtype=float)
    if np.all(~np.isfinite(xs)):
        return np.zeros_like(xs), 0.0, 1.0
    xs[~np.isfinite(xs)] = np.nan
    vmin = np.nanmin(xs)
    vmax = np.nanmax(xs)
    if not np.isfinite(vmin) or not np.isfinite(vmax) or abs(vmax - vmin) < 1e-12:
        return np.zeros_like(xs), vmin, vmax
    return (xs - vmin) / (vmax - vmin), vmin, vmax

def add_functions_to_files(files: List[File], functions: List[Function], language:str="python"):
    for function in functions:
        if language == "python":
            # 检查文件代码中是否包含函数代码
            for file in files:
                if function.func_code in file.file_code:
                    function.func_file = file.file_name
                    file.func_list.append(function)
                    break
        elif language == "java":
            # 使用函数全名中的类名
            class_name = function.func_file
            for file in files:
                if file.file_name == class_name:
                    file.func_list.append(function)
                    break

def compute_link(method_cluster):
    global func_adj_matrix
    if func_adj_matrix is None:
        return np.zeros((len(method_cluster.cluster_func_list), len(method_cluster.cluster_func_list)))

    link_matrix = np.zeros((len(method_cluster.cluster_func_list), len(method_cluster.cluster_func_list)))
    i = 0 
    for function in method_cluster.cluster_func_list:
        j = 0
        for other_function in method_cluster.cluster_func_list:
            if i == j:
                j += 1
                continue
            if func_adj_matrix[function.func_id][other_function.func_id] != 0:
                link_matrix[i][j] = 1
                link_matrix[j][i] = 1
            j += 1
        i += 1
    return link_matrix

def normalize_01(M: np.ndarray, eps=1e-12) -> np.ndarray:
    M = symmetrize_zero_diag(M)
    if M.size == 0:
        return np.zeros_like(M)
    mmin, mmax = M.min(), M.max()
    if not np.isfinite(mmin) or not np.isfinite(mmax) or (mmax - mmin) < eps:
        return np.zeros_like(M)
    M = (M - mmin) / (mmax - mmin)
    np.fill_diagonal(M, 0.0)
    return M

def fuse_weights_func(S: np.ndarray, L: np.ndarray, a: float) -> np.ndarray:
    S_ = normalize_01(S)
    L_ = normalize_01(L)
    W = a * S_ + (1 - a) * L_
    return symmetrize_zero_diag(W)

def sparsify_threshold(W: np.ndarray, tau: Optional[float] = None) -> np.ndarray:
    if tau is None or tau <= 0:
        return symmetrize_zero_diag(W)
    W2 = W.copy()
    W2[W2 < tau] = 0.0
    return symmetrize_zero_diag(W2)

def run_leiden_on_W(W: np.ndarray, gamma: float, seed: int, objective: str = "CPM", n_iterations: int = -1) -> Tuple[np.ndarray, float]:
    G = build_graph(W)
    if objective.upper() == "CPM":
        part = la.find_partition(G, la.CPMVertexPartition, weights='weight', resolution_parameter=gamma, seed=seed, n_iterations=n_iterations)
    elif objective.upper() in ("RB", "RBCONFIGURATION", "RBCONFIG"):
        part = la.find_partition(G, la.RBConfigurationVertexPartition, weights='weight', resolution_parameter=gamma, seed=seed, n_iterations=n_iterations)
    else:
        raise ValueError("objective must be 'CPM' or 'RBConfiguration'")
    labels = np.array(part.membership, dtype=int)
    return labels, float(part.quality())

def cluster_density_std(W: np.ndarray, labels: np.ndarray) -> float:
    labels = np.asarray(labels)
    densities = []
    for c in np.unique(labels):
        idx = np.where(labels == c)[0]
        m = idx.size
        if m <= 1:
            continue
        sub = W[np.ix_(idx, idx)]
        dens = sub.sum() / (m * (m - 1))
        densities.append(dens)
    return float(np.std(densities)) if densities else float("inf")

def coassociation_matrix(partitions: List[np.ndarray]) -> np.ndarray:
    n = len(partitions[0])
    C = np.zeros((n, n), dtype=np.float32)
    for labels in partitions:
        labels = np.asarray(labels)
        for c in np.unique(labels):
            idx = np.where(labels == c)[0]
            if idx.size == 0:
                continue
            C[np.ix_(idx, idx)] += 1.0
    C /= len(partitions)
    np.fill_diagonal(C, 1.0)
    return C

def pairwise_mean_ari(partitions: List[np.ndarray]) -> float:
    if len(partitions) <= 1:
        return 1.0
    ARIs = []
    for i in range(len(partitions)):
        for j in range(i + 1, len(partitions)):
            ARIs.append(adjusted_rand_score(partitions[i], partitions[j]))
    return float(np.mean(ARIs)) if ARIs else 1.0

def safe_silhouette_from_similarity(W: np.ndarray, labels: np.ndarray, use_silhouette: bool = False, sample_size: Optional[int] = None, rng: int = 42) -> Optional[float]:
    if not use_silhouette:
        return None
    dist = 1.0 - np.clip(W, 0.0, 1.0)
    np.fill_diagonal(dist, 0.0)
    labels = np.asarray(labels)
    uniq, counts = np.unique(labels, return_counts=True)
    if uniq.size < 2 or np.any(counts < 2):
        return None
    if sample_size is not None and sample_size < len(labels):
        rnd = np.random.default_rng(rng)
        idx = rnd.choice(len(labels), size=sample_size, replace=False)
        dist = dist[np.ix_(idx, idx)]
        labels = labels[idx]
    try:
        return float(silhouette_score(dist, labels, metric="precomputed"))
    except Exception:
        return None

def _minmax(xs: List[float]) -> Tuple[np.ndarray, float, float]:
    arr = np.array(xs, dtype=float)
    arr[~np.isfinite(arr)] = np.nan
    if np.all(np.isnan(arr)):
        return np.zeros_like(arr), 0.0, 1.0
    vmin = np.nanmin(arr)
    vmax = np.nanmax(arr)
    if not np.isfinite(vmin) or not np.isfinite(vmax) or abs(vmax - vmin) < 1e-12:
        return np.zeros_like(arr), vmin, vmax
    return (arr - vmin) / (vmax - vmin), vmin, vmax

def _extract_identifiers(code: str):
    # 提取 Java/Python 标识符 (字母或下划线开头)
    return set(re.findall(r'[A-Za-z_][A-Za-z0-9_]*', code))

def compute_link_matrix(files: List[File]):
    link_matrix = np.zeros((len(files), len(files)))
    id_sets = {f.file_id: _extract_identifiers(f.file_code) for f in files}
    for file in files:
        name = file.file_name
        for other_file in files:
            if file.file_id == other_file.file_id:
                continue
            if (name in id_sets[other_file.file_id]) or (name == other_file.file_name):
                link_matrix[file.file_id][other_file.file_id] = 1
                link_matrix[other_file.file_id][file.file_id] = 1
    return link_matrix

def extract_comments_from_code(code: str, language: str="python") -> str:
    """
    从代码中提取注释
    支持Python和Java的常见注释格式

    Args:
        code: 函数代码字符串
        language: 代码语言，支持"python"或"java"

    Returns:
        提取的注释文本，多个注释用换行符连接
    """
    # 类型检查和转换：确保code是字符串类型
    if code is None:
        return ""
    if not isinstance(code, str):
        # 尝试转换为字符串
        try:
            code = str(code)
        except Exception:
            return ""

    # 如果转换后是空字符串或只包含空白字符
    if not code or not code.strip():
        return ""

    comments = []

    if language == "python":
        # 1. 提取Python docstring（使用ast）
        try:
            tree = ast.parse(code)
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    docstring = ast.get_docstring(node)
                    if docstring:
                        comments.append(docstring)
        except (SyntaxError, ValueError):
            # 如果代码不完整无法解析，继续使用其他方法
            pass

        # 2. 提取Python单行注释 (# comment)
        try:
            tokens = tokenize.generate_tokens(StringIO(code).readline)
            for tok in tokens:
                if tok.type == tokenize.COMMENT:
                    # 移除注释符号(#)和前后空白
                    comment_text = tok.string.strip().lstrip('#').strip()
                    if comment_text and comment_text not in comments:
                        comments.append(comment_text)
        except (tokenize.TokenError, SyntaxError):
            # 如果tokenize失败，使用正则表达式作为备用
            single_line_comments = re.findall(r'#\s*(.+?)(?=\n|$)', code)
            for comment in single_line_comments:
                comment = comment.strip()
                if comment and comment not in comments:
                    comments.append(comment)

    elif language == "java":
        # 1. 提取JavaDoc注释 /** ... */
        javadoc_comments = re.findall(r'/\*\*\s*(.+?)\s*\*/', code, re.DOTALL)
        for comment in javadoc_comments:
            # 清理JavaDoc注释，移除每行的*符号和前导空格
            lines = []
            for line in comment.split('\n'):
                cleaned_line = line.strip().lstrip('*').strip()
                if cleaned_line:
                    lines.append(cleaned_line)
            cleaned_comment = '.'.join(lines).strip()
            if cleaned_comment and cleaned_comment not in comments:
                comments.append(cleaned_comment)

        # 2. 提取多行注释 /* ... */
        multiline_comments = re.findall(r'/\*\s*(.+?)\s*\*/', code, re.DOTALL)
        for comment in multiline_comments:
            # 清理多行注释，移除每行的*符号
            lines = []
            for line in comment.split('\n'):
                cleaned_line = line.strip().lstrip('*').strip()
                if cleaned_line:
                    lines.append(cleaned_line)
            cleaned_comment = '.'.join(lines).strip()
            if cleaned_comment and cleaned_comment not in comments:
                comments.append(cleaned_comment)

        # 3. 提取单行注释 // comment
        java_single_comments = re.findall(r'//\s*(.+?)(?=\n|$)', code)
        for comment in java_single_comments:
            comment = comment.strip()
            if comment and comment not in comments:
                comments.append(comment)

    # 合并所有注释为字符串
    if comments:
        return '.'.join(comments)
    else:
        return ""

def call_with_retry(fn, retries=5, base_delay=0.5, max_delay=8.0):
    for i in range(retries):
        try:
            return fn()
        except Exception as e:
            msg = str(e)
            if "429" not in msg and "RateLimit" not in msg and "upstream" not in msg:
                raise
            delay = min(max_delay, base_delay * (2 ** i)) * (1 + random.random() * 0.25)
            time.sleep(delay)
    return fn()

def code_t5_summary(functions: List[Function], language:str="python") -> List[Function]:
    tokenizer = RobertaTokenizer.from_pretrained('Salesforce/codet5-base-multi-sum')
    model = T5ForConditionalGeneration.from_pretrained('Salesforce/codet5-base-multi-sum')

    for function in functions:
        function.func_desc = extract_comments_from_code(function.func_code, language=language)
        if function.func_desc != "":
            continue
        # 确保func_code是字符串类型
        text = function.func_code
        if not isinstance(text, str):
            if text is None:
                text = ""
            else:
                text = str(text)
        if not text or not text.strip():
            function.func_desc = function.func_name
            continue
        # 如果text超长则截断
        # CodeT5模型的最大输入长度通常是512 tokens
        max_length = 512
        # 先检查原始文本长度（不添加special tokens，更准确）
        temp_encoded = tokenizer(text, add_special_tokens=False)
        original_length = len(temp_encoded['input_ids'])

        # 使用truncation参数自动截断超长文本
        encoded = tokenizer(text, return_tensors="pt", truncation=True, max_length=max_length)
        input_ids = encoded.input_ids

        # 如果原始文本被截断，给出警告
        if original_length > max_length:
            print(f"警告: 函数 {function.func_name} 的代码过长 ({original_length} tokens)，已截断至 {max_length} tokens")

        generated_ids = model.generate(input_ids, max_length=40)
        function.func_desc = tokenizer.decode(generated_ids[0], skip_special_tokens=True)
    return functions
